import{_ as p,a0 as d,w as o,s as r,I as e,x as i,a1 as n,A as l,ao as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Linux 中找到并删除重复文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中找到并删除重复文件 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中找到并删除重复文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中找到并删除重复文件 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180927 How To Find And Delete Duplicate Files In Linux","title":"如何在 Linux 中找到并删除重复文件","tag":"201810","desc":""},"relativePath":"201810/20180927 How To Find And Delete Duplicate Files In Linux.md","filePath":"[post].md"}'),h={name:"201810/20180927 How To Find And Delete Duplicate Files In Linux.md"};function g(u,s,k,c,b,f){const a=d("Link");return o(),r("div",null,[s[38]||(s[38]=e("h1",{id:"如何在-linux-中找到并删除重复文件",tabindex:"-1"},[i("如何在 Linux 中找到并删除重复文件 "),e("a",{class:"header-anchor",href:"#如何在-linux-中找到并删除重复文件","aria-label":"Permalink to “如何在 Linux 中找到并删除重复文件”"},"​")],-1)),s[39]||(s[39]=e("p",null,[e("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/09/Find-And-Delete-Duplicate-Files-720x340.png",alt:""})],-1)),s[40]||(s[40]=e("p",null,"在编辑或修改配置文件或旧文件前，我经常会把它们备份到硬盘的某个地方，因此我如果意外地改错了这些文件，我可以从备份中恢复它们。但问题是如果我忘记清理备份文件，一段时间之后，我的磁盘会被这些大量重复文件填满 —— 我觉得要么是懒得清理这些旧文件，要么是担心可能会删掉重要文件。如果你们像我一样，在类 Unix 操作系统中，大量多版本的相同文件放在不同的备份目录，你可以使用下面的工具找到并删除重复文件。",-1)),s[41]||(s[41]=e("p",null,[e("strong",null,"提醒一句：")],-1)),e("p",null,[s[1]||(s[1]=i("在删除重复文件的时请尽量小心。如果你不小心，也许会导致",-1)),n(a,{href:"https://www.ostechnix.com/prevent-files-folders-accidental-deletion-modification-linux/"},{default:l(()=>[...s[0]||(s[0]=[i("意外丢失数据",-1)])]),_:1}),s[2]||(s[2]=i("。我建议你在使用这些工具的时候要特别注意。",-1))]),s[42]||(s[42]=e("h3",{id:"在-linux-中找到并删除重复文件",tabindex:"-1"},[i("在 Linux 中找到并删除重复文件 "),e("a",{class:"header-anchor",href:"#在-linux-中找到并删除重复文件","aria-label":"Permalink to “在 Linux 中找到并删除重复文件”"},"​")],-1)),s[43]||(s[43]=e("p",null,"出于本指南的目的，我将讨论下面的三个工具：",-1)),s[44]||(s[44]=e("ol",null,[e("li",null,"Rdfind"),e("li",null,"Fdupes"),e("li",null,"FSlint")],-1)),s[45]||(s[45]=e("p",null,"这三个工具是自由开源的，且运行在大多数类 Unix 系统中。",-1)),s[46]||(s[46]=e("h4",{id:"_1-rdfind",tabindex:"-1"},[i("1. Rdfind "),e("a",{class:"header-anchor",href:"#_1-rdfind","aria-label":"Permalink to “1. Rdfind”"},"​")],-1)),e("p",null,[s[4]||(s[4]=e("strong",null,"Rdfind",-1)),s[5]||(s[5]=i(" 意即 ",-1)),s[6]||(s[6]=e("strong",null,"r",-1)),s[7]||(s[7]=i("edundant ",-1)),s[8]||(s[8]=e("strong",null,"d",-1)),s[9]||(s[9]=i("ata ",-1)),s[10]||(s[10]=e("strong",null,"find",-1)),s[11]||(s[11]=i("（冗余数据查找），是一个通过访问目录和子目录来找出重复文件的自由开源的工具。它是基于文件内容而不是文件名来比较。Rdfind 使用",-1)),s[12]||(s[12]=e("strong",null,"排序",-1)),s[13]||(s[13]=i("算法来区分原始文件和重复文件。如果你有两个或者更多的相同文件，Rdfind 会很智能的找到原始文件并认定剩下的文件为重复文件。一旦找到副本文件，它会向你报告。你可以决定是删除还是使用",-1)),n(a,{href:"https://www.ostechnix.com/explaining-soft-link-and-hard-link-in-linux-with-examples/"},{default:l(()=>[...s[3]||(s[3]=[i("硬链接或者符号（软）链接",-1)])]),_:1}),s[14]||(s[14]=i("代替它们。",-1))]),s[47]||(s[47]=e("p",null,[e("strong",null,"安装 Rdfind")],-1)),e("p",null,[s[17]||(s[17]=i("Rdfind 存在于 ",-1)),n(a,{href:"https://aur.archlinux.org/packages/rdfind/"},{default:l(()=>[...s[15]||(s[15]=[i("AUR",-1)])]),_:1}),s[18]||(s[18]=i(" 中。因此，在基于 Arch 的系统中，你可以像下面一样使用任一如 ",-1)),n(a,{href:"https://www.ostechnix.com/yay-found-yet-another-reliable-aur-helper/"},{default:l(()=>[...s[16]||(s[16]=[i("Yay",-1)])]),_:1}),s[19]||(s[19]=i(" AUR 程序助手安装它。",-1))]),s[48]||(s[48]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yay -S rdfind</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install rdfind</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install rdfind</span></span></code></pre></div><p>在 RHEL、CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install epel-release</span></span>
<span class="line"><span>$ sudo yum install rdfind</span></span></code></pre></div><p><strong>用法</strong></p><p>一旦安装完成，仅带上目录路径运行 Rdfind 命令就可以扫描重复文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind ~/Downloads</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/rdfind-1.png" alt=""></p><p>正如你看到上面的截屏，Rdfind 命令将扫描 <code>~/Downloads</code> 目录，并将结果存储到当前工作目录下一个名为 <code>results.txt</code> 的文件中。你可以在 <code>results.txt</code> 文件中看到可能是重复文件的名字。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat results.txt</span></span>
<span class="line"><span># Automatically generated</span></span>
<span class="line"><span># duptype id depth size device inode priority name</span></span>
<span class="line"><span>DUPTYPE_FIRST_OCCURRENCE 1469 8 9 2050 15864884 1 /home/sk/Downloads/tor-browser_en-US/Browser/TorBrowser/Tor/PluggableTransports/fte/tests/dfas/test5.regex</span></span>
<span class="line"><span>DUPTYPE_WITHIN_SAME_TREE -1469 8 9 2050 15864886 1 /home/sk/Downloads/tor-browser_en-US/Browser/TorBrowser/Tor/PluggableTransports/fte/tests/dfas/test6.regex</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>DUPTYPE_FIRST_OCCURRENCE 13 0 403635 2050 15740257 1 /home/sk/Downloads/Hyperledger(1).pdf</span></span>
<span class="line"><span>DUPTYPE_WITHIN_SAME_TREE -13 0 403635 2050 15741071 1 /home/sk/Downloads/Hyperledger.pdf</span></span>
<span class="line"><span># end of file</span></span></code></pre></div><p>通过检查 <code>results.txt</code> 文件，你可以很容易的找到那些重复文件。如果愿意你可以手动的删除它们。</p><p>此外，你可在不修改其他事情情况下使用 <code>-dryrun</code> 选项找出所有重复文件，并在终端上输出汇总信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind -dryrun true ~/Downloads</span></span></code></pre></div><p>一旦找到重复文件，你可以使用硬链接或符号链接代替他们。</p><p>使用硬链接代替所有重复文件，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind -makehardlinks true ~/Downloads</span></span></code></pre></div><p>使用符号链接/软链接代替所有重复文件，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind -makesymlinks true ~/Downloads</span></span></code></pre></div><p>目录中有一些空文件，也许你想忽略他们，你可以像下面一样使用 <code>-ignoreempty</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind -ignoreempty true ~/Downloads</span></span></code></pre></div><p>如果你不再想要这些旧文件，删除重复文件，而不是使用硬链接或软链接代替它们。</p><p>删除重复文件，就运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind -deleteduplicates true ~/Downloads</span></span></code></pre></div><p>如果你不想忽略空文件，并且和所哟重复文件一起删除。运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind -deleteduplicates true -ignoreempty false ~/Downloads</span></span></code></pre></div><p>更多细节，参照帮助部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rdfind --help</span></span></code></pre></div><p>手册页：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man rdfind</span></span></code></pre></div><h4 id="_2-fdupes" tabindex="-1">2. Fdupes <a class="header-anchor" href="#_2-fdupes" aria-label="Permalink to “2. Fdupes”">​</a></h4><p><strong>Fdupes</strong> 是另一个在指定目录以及子目录中识别和移除重复文件的命令行工具。这是一个使用 C 语言编写的自由开源工具。Fdupes 通过对比文件大小、部分 MD5 签名、全部 MD5 签名，最后执行逐个字节对比校验来识别重复文件。</p><p>与 Rdfind 工具类似，Fdupes 附带非常少的选项来执行操作，如：</p><ul><li>在目录和子目录中递归的搜索重复文件</li><li>从计算中排除空文件和隐藏文件</li><li>显示重复文件大小</li><li>出现重复文件时立即删除</li><li>使用不同的拥有者/组或权限位来排除重复文件</li><li>更多</li></ul><p><strong>安装 Fdupes</strong></p><p>Fdupes 存在于大多数 Linux 发行版的默认仓库中。</p><p>在 Arch Linux 和它的变种如 Antergos、Manjaro Linux 上，如下使用 Pacman 安装它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S fdupes</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install fdupes</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install fdupes</span></span></code></pre></div><p>在 RHEL、CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install epel-release</span></span>
<span class="line"><span>$ sudo yum install fdupes</span></span></code></pre></div><p><strong>用法</strong></p><p>Fdupes 用法非常简单。仅运行下面的命令就可以在目录中找到重复文件，如：<code>~/Downloads</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes ~/Downloads</span></span></code></pre></div><p>我系统中的样例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/home/sk/Downloads/Hyperledger.pdf</span></span>
<span class="line"><span>/home/sk/Downloads/Hyperledger(1).pdf</span></span></code></pre></div><p>你可以看到，在 <code>/home/sk/Downloads/</code> 目录下有一个重复文件。它仅显示了父级目录中的重复文件。如何显示子目录中的重复文件？像下面一样，使用 <code>-r</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes -r ~/Downloads</span></span></code></pre></div><p>现在你将看到 <code>/home/sk/Downloads/</code> 目录以及子目录中的重复文件。</p><p>Fdupes 也可用来从多个目录中迅速查找重复文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes ~/Downloads ~/Documents/ostechnix</span></span></code></pre></div><p>你甚至可以搜索多个目录，递归搜索其中一个目录，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes ~/Downloads -r ~/Documents/ostechnix</span></span></code></pre></div><p>上面的命令将搜索 <code>~/Downloads</code> 目录，<code>~/Documents/ostechnix</code> 目录和它的子目录中的重复文件。</p><p>有时，你可能想要知道一个目录中重复文件的大小。你可以使用 <code>-S</code> 选项，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes -S ~/Downloads</span></span>
<span class="line"><span>403635 bytes each:</span></span>
<span class="line"><span>/home/sk/Downloads/Hyperledger.pdf</span></span>
<span class="line"><span>/home/sk/Downloads/Hyperledger(1).pdf</span></span></code></pre></div><p>类似的，为了显示父目录和子目录中重复文件的大小，使用 <code>-Sr</code> 选项。</p><p>我们可以在计算时分别使用 <code>-n</code> 和 <code>-A</code> 选项排除空白文件以及排除隐藏文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes -n ~/Downloads</span></span>
<span class="line"><span>$ fdupes -A ~/Downloads</span></span></code></pre></div><p>在搜索指定目录的重复文件时，第一个命令将排除零长度文件，后面的命令将排除隐藏文件。</p><p>汇总重复文件信息，使用 <code>-m</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes -m ~/Downloads</span></span>
<span class="line"><span>1 duplicate files (in 1 sets), occupying 403.6 kilobytes</span></span></code></pre></div><p>删除所有重复文件，使用 <code>-d</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes -d ~/Downloads</span></span></code></pre></div><p>样例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[1] /home/sk/Downloads/Hyperledger Fabric Installation.pdf</span></span>
<span class="line"><span>[2] /home/sk/Downloads/Hyperledger Fabric Installation(1).pdf</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Set 1 of 1, preserve files [1 - 2, all]:</span></span></code></pre></div><p>这个命令将提示你保留还是删除所有其他重复文件。输入任一号码保留相应的文件，并删除剩下的文件。当使用这个选项的时候需要更加注意。如果不小心，你可能会删除原文件。</p><p>如果你想要每次保留每个重复文件集合的第一个文件，且无提示的删除其他文件，使用 <code>-dN</code> 选项（不推荐）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes -dN ~/Downloads</span></span></code></pre></div><p>当遇到重复文件时删除它们，使用 <code>-I</code> 标志。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes -I ~/Downloads</span></span></code></pre></div><p>关于 Fdupes 的更多细节，查看帮助部分和 man 页面。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fdupes --help</span></span>
<span class="line"><span>$ man fdupes</span></span></code></pre></div><h4 id="_3-fslint" tabindex="-1">3. FSlint <a class="header-anchor" href="#_3-fslint" aria-label="Permalink to “3. FSlint”">​</a></h4><p><strong>FSlint</strong> 是另外一个查找重复文件的工具，有时我用它去掉 Linux 系统中不需要的重复文件并释放磁盘空间。不像另外两个工具，FSlint 有 GUI 和 CLI 两种模式。因此对于新手来说它更友好。FSlint 不仅仅找出重复文件，也找出坏符号链接、坏名字文件、临时文件、坏的用户 ID、空目录和非精简的二进制文件等等。</p><p><strong>安装 FSlint</strong></p>`,81)),e("p",null,[s[21]||(s[21]=i("FSlint 存在于 ",-1)),n(a,{href:"https://aur.archlinux.org/packages/fslint/"},{default:l(()=>[...s[20]||(s[20]=[i("AUR",-1)])]),_:1}),s[22]||(s[22]=i("，因此你可以使用任一 AUR 助手安装它。",-1))]),s[49]||(s[49]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yay -S fslint</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install fslint</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install fslint</span></span></code></pre></div><p>在 RHEL，CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install epel-release</span></span>
<span class="line"><span>$ sudo yum install fslint</span></span></code></pre></div><p>一旦安装完成，从菜单或者应用程序启动器启动它。</p><p>FSlint GUI 展示如下：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/09/fslint-1.png" alt=""></p><p>如你所见，FSlint 界面友好、一目了然。在 “Search path” 栏，添加你要扫描的目录路径，点击左下角 “Find” 按钮查找重复文件。验证递归选项可以在目录和子目录中递归的搜索重复文件。FSlint 将快速的扫描给定的目录并列出重复文件。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/fslint-2.png" alt=""></p><p>从列表中选择那些要清理的重复文件，也可以选择 “Save”、“Delete”、“Merge” 和 “Symlink” 操作他们。</p><p>在 “Advanced search parameters” 栏，你可以在搜索重复文件的时候指定排除的路径。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/09/fslint-3.png" alt=""></p><p><strong>FSlint 命令行选项</strong></p><p>FSlint 提供下面的 CLI 工具集在你的文件系统中查找重复文件。</p><ul><li><code>findup</code> — 查找重复文件</li><li><code>findnl</code> — 查找名称规范（有问题的文件名）</li><li><code>findu8</code> — 查找非法的 utf8 编码的文件名</li><li><code>findbl</code> — 查找坏链接（有问题的符号链接）</li><li><code>findsn</code> — 查找同名文件（可能有冲突的文件名）</li><li><code>finded</code> — 查找空目录</li><li><code>findid</code> — 查找死用户的文件</li><li><code>findns</code> — 查找非精简的可执行文件</li><li><code>findrs</code> — 查找文件名中多余的空白</li><li><code>findtf</code> — 查找临时文件</li><li><code>findul</code> — 查找可能未使用的库</li><li><code>zipdir</code> — 回收 ext2 目录项下浪费的空间</li></ul><p>所有这些工具位于 <code>/usr/share/fslint/fslint/fslint</code> 下面。</p><p>例如，在给定的目录中查找重复文件，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /usr/share/fslint/fslint/findup ~/Downloads/</span></span></code></pre></div><p>类似的，找出空目录命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /usr/share/fslint/fslint/finded ~/Downloads/</span></span></code></pre></div><p>获取每个工具更多细节，例如：<code>findup</code>，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /usr/share/fslint/fslint/findup --help</span></span></code></pre></div><p>关于 FSlint 的更多细节，参照帮助部分和 man 页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /usr/share/fslint/fslint/fslint --help</span></span>
<span class="line"><span>$ man fslint</span></span></code></pre></div><h5 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h5><p>现在你知道在 Linux 中，使用三个工具来查找和删除不需要的重复文件。这三个工具中，我经常使用 Rdfind。这并不意味着其他的两个工具效率低下，因为到目前为止我更喜欢 Rdfind。好了，到你了。你的最喜欢哪一个工具呢？为什么？在下面的评论区留言让我们知道吧。</p><p>就到这里吧。希望这篇文章对你有帮助。更多的好东西就要来了，敬请期待。</p><p>谢谢！</p><hr>`,32)),e("p",null,[s[24]||(s[24]=i("via: ",-1)),n(a,{href:"https://www.ostechnix.com/how-to-find-and-delete-duplicate-files-in-linux/"},{default:l(()=>[...s[23]||(s[23]=[i("https://www.ostechnix.com/how-to-find-and-delete-duplicate-files-in-linux/",-1)])]),_:1})]),e("p",null,[s[29]||(s[29]=i("作者：",-1)),n(a,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>[...s[25]||(s[25]=[i("SK",-1)])]),_:1}),s[30]||(s[30]=i(" 选题：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[26]||(s[26]=[i("lujun9972",-1)])]),_:1}),s[31]||(s[31]=i(" 译者：",-1)),n(a,{href:"https://github.com/pygmalion666"},{default:l(()=>[...s[27]||(s[27]=[i("pygmalion666",-1)])]),_:1}),s[32]||(s[32]=i(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[28]||(s[28]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[35]||(s[35]=i("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[33]||(s[33]=[i("LCTT",-1)])]),_:1}),s[36]||(s[36]=i(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:l(()=>[...s[34]||(s[34]=[i("Linux中国",-1)])]),_:1}),s[37]||(s[37]=i(" 荣誉推出",-1))])])}const C=p(h,[["render",g]]);export{x as __pageData,C as default};
